#include <iostream>
#include <vector>
using namespace std;

int main() {   //@ @layout open:container
    vector<int> v;   //@ @tts [next] 從空的 vector 開始
    v.push_back(3);   //@ @guide {v} @tts [next] 放進三
    v.push_back(1);   //@ @guide {v} @tts [next] 再放進一
    v.push_back(4);   //@ @guide {v} @tts [next] 再放進四
    v.pop_back();   //@ @guide {v} @tts [next] 拿掉最後一個
    cout << v.size() << endl;   //@ @guide {v} @tts [next] 現在剩下兩個
    return 0;   //@ @tts [continue] 程式結束
}
